const{chromium}=require('playwright');(async()=>{const b=await chromium.launch({headless:true,executablePath:'/ms-playwright/chromium-1187/chrome-linux/chrome',args:['--no-sandbox']});const p=await b.newPage({viewport:{width:1440,height:900}});p.on('pageerror',e=>console.log('PAGEERROR',e.message));await p.route('https://tile.openstreetmap.org/**',r=>r.fulfill({status:200,contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/pN8AAAAASUVORK5CYII=','base64')}));await p.goto('http://host.docker.internal:8080/?view=data-dashboard',{waitUntil:'domcontentloaded'});await p.waitForTimeout(10000);await p.locator('#rdOpportunityMap').scrollIntoViewIfNeeded();await p.waitForTimeout(1500);console.log('before',await p.evaluate(()=>({html:document.querySelector('#rdOpportunityMap').innerHTML.slice(0,1000),rect:document.querySelector('#rdOpportunityMap').getBoundingClientRect().toJSON(),markers:document.querySelectorAll('#rdOpportunityMap .leaflet-marker-icon').length,clusters:document.querySelectorAll('#rdOpportunityMap .marker-cluster').length,stats:document.querySelector('#rdGeoStats').innerText,title:document.querySelector('#rdMapTitle').innerText})));for(let i=0;i<6;i++){let m=p.locator('#rdOpportunityMap .leaflet-marker-icon').last();console.log('click',i,'count',await p.locator('#rdOpportunityMap .leaflet-marker-icon').count(),'text',await m.innerText().catch(()=>''),'html',(await m.getAttribute('class').catch(()=>'')));if(!(await p.locator('#rdOpportunityMap .leaflet-marker-icon').count()))break;await m.click({force:true});await p.waitForTimeout(500);console.log('popup',await p.locator('#rdOpportunityMap [data-map-open]').count(),'markers',await p.locator('#rdOpportunityMap .leaflet-marker-icon').count(),'clusters',await p.locator('#rdOpportunityMap .marker-cluster').count());}await b.close()})().catch(e=>{console.error(e);process.exit(1)});